"use client";

import React, { useState, useMemo } from "react";
import PageHeader from "@/components/common/PageHeader";
import { 
  Calendar as CalendarIcon, 
  ChevronLeft, 
  ChevronRight, 
  Info, 
  CheckCircle2, 
  AlertCircle,
  X
} from "lucide-react";

// Mock Leave Balances
const LEAVE_BALANCES = {
  annual: 18,
  sick: 12,
  casual: 5,
  unpaid: 999
};

export default function RequestAbsencePage() {
  const [step, setStep] = useState(1); // 1: Date Selection, 2: Details
  const [selectedRange, setSelectedRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [formData, setFormData] = useState({
    leaveType: "annual",
    reason: "",
  });

  // --- Logic: Calculate Working Days (Skipping Weekends) ---
  const workingDays = useMemo(() => {
    if (!selectedRange.start || !selectedRange.end) return 0;
    let count = 0;
    let cur = new Date(selectedRange.start);
    let end = new Date(selectedRange.end);
    while (cur <= end) {
      const day = cur.getDay();
      if (day !== 0 && day !== 6) count++;
      cur.setDate(cur.getDate() + 1);
    }
    return count;
  }, [selectedRange]);

  const handleDateClick = (date: string) => {
    if (!selectedRange.start || (selectedRange.start && selectedRange.end)) {
      setSelectedRange({ start: date, end: "" });
    } else {
      const start = new Date(selectedRange.start);
      const clicked = new Date(date);
      if (clicked < start) {
        setSelectedRange({ start: date, end: "" });
      } else {
        setSelectedRange({ ...selectedRange, end: date });
      }
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    alert(`Request for ${workingDays} days submitted!`);
    // Reset
    setStep(1);
    setSelectedRange({ start: "", end: "" });
  };

  return (
    <div className="mx-auto max-w-5xl px-4 py-8">
      <PageHeader
        title="Request Absence"
        subtitle="Select dates and provide details for your leave request."
        breadcrumbs={[{ label: "Time Management" }, { label: "Request Absence" }]}
      />

      <div className="mt-8 grid grid-cols-1 gap-8 lg:grid-cols-12">
        {/* LEFT: The Interactive Calendar (Step 1) */}
        <div className="lg:col-span-8">
          <div className="rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-gray-800 dark:bg-white/[0.03]">
            <div className="mb-6 flex items-center justify-between">
              <h3 className="text-lg font-bold">Select Date Range</h3>
              <div className="flex gap-2 text-sm text-gray-500">
                <span className="flex items-center gap-1"><span className="h-3 w-3 rounded-full bg-blue-600"></span> Selected</span>
                <span className="flex items-center gap-1"><span className="h-3 w-3 rounded-full bg-gray-100 border"></span> Weekend</span>
              </div>
            </div>

            {/* Simple Grid Calendar (Mocking January 2026) */}
            <div className="grid grid-cols-7 gap-1 text-center text-sm font-medium text-gray-400">
              {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => <div key={d} className="py-2">{d}</div>)}
              {Array.from({ length: 31 }).map((_, i) => {
                const day = i + 1;
                const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                const isSelected = selectedRange.start === dateStr || selectedRange.end === dateStr;
                const inRange = selectedRange.start && selectedRange.end && dateStr > selectedRange.start && dateStr < selectedRange.end;
                const isWeekend = (day + 4) % 7 === 0 || (day + 4) % 7 === 6; // Rough Sat/Sun logic for Jan '26

                return (
                  <button
                    key={day}
                    onClick={() => handleDateClick(dateStr)}
                    className={`h-12 rounded-lg transition-all ${
                      isSelected ? "bg-blue-600 text-white" : 
                      inRange ? "bg-blue-50 text-blue-600 dark:bg-blue-500/10" : 
                      isWeekend ? "bg-gray-50 text-gray-300 dark:bg-white/5" : "hover:bg-gray-100 dark:hover:bg-white/5"
                    }`}
                  >
                    {day}
                  </button>
                );
              })}
            </div>

            {selectedRange.start && selectedRange.end && (
              <div className="mt-8 flex items-center justify-between border-t pt-6 dark:border-gray-800">
                <div className="flex items-center gap-3">
                    <CalendarIcon className="h-5 w-5 text-blue-600" />
                    <span className="text-sm font-semibold">
                        {selectedRange.start} to {selectedRange.end}
                    </span>
                </div>
                <div className="flex gap-3">
                    <button onClick={() => setSelectedRange({start:"", end:""})} className="px-4 py-2 text-sm font-medium text-gray-500 hover:text-gray-700">Clear</button>
                    <button onClick={() => setStep(2)} className="rounded-lg bg-blue-600 px-6 py-2 text-sm font-bold text-white hover:bg-blue-700">Continue</button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* RIGHT: Detail Entry (Step 2) */}
        <div className="lg:col-span-4 space-y-6">
          <div className={`rounded-2xl border border-gray-200 bg-white p-6 shadow-sm transition-opacity dark:border-gray-800 dark:bg-white/[0.03] ${step === 1 ? 'opacity-40 pointer-events-none' : 'opacity-100'}`}>
            <div className="mb-6 flex items-center justify-between">
                <h3 className="font-bold">Finalize Details</h3>
                {step === 2 && <button onClick={() => setStep(1)} className="text-gray-400 hover:text-gray-600"><X className="h-4 w-4"/></button>}
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-gray-400 uppercase">Leave Type</label>
                <select 
                   value={formData.leaveType}
                   onChange={(e) => setFormData({...formData, leaveType: e.target.value})}
                   className="w-full rounded-lg border border-gray-200 bg-transparent p-3 text-sm focus:ring-2 focus:ring-blue-500 dark:border-gray-700"
                >
                  <option value="annual">Annual Leave</option>
                  <option value="sick">Sick Leave</option>
                  <option value="casual">Casual Leave</option>
                </select>
              </div>

              <div className="space-y-1">
                <label className="text-xs font-bold text-gray-400 uppercase">Reason</label>
                <textarea 
                    required
                    className="w-full rounded-lg border border-gray-200 bg-transparent p-3 text-sm focus:ring-2 focus:ring-blue-500 dark:border-gray-700"
                    placeholder="Enter reason..."
                    onChange={(e) => setFormData({...formData, reason: e.target.value})}
                    rows={3}
                />
              </div>

              <div className="rounded-xl bg-blue-50 p-4 dark:bg-blue-500/5">
                <div className="flex justify-between text-sm">
                    <span className="text-blue-700">Net Business Days:</span>
                    <span className="font-bold text-blue-900 dark:text-blue-100">{workingDays} Days</span>
                </div>
              </div>

              <button 
                type="submit"
                className="w-full rounded-lg bg-blue-600 py-3 font-bold text-white shadow-lg shadow-blue-500/20 hover:bg-blue-700"
              >
                Submit Request
              </button>
            </form>
          </div>

          {/* Quick Balance Glance */}
          <div className="rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-gray-800 dark:bg-white/[0.03]">
             <h4 className="text-xs font-bold text-gray-400 uppercase mb-4">Your Balances</h4>
             <div className="space-y-3">
                <BalanceItem label="Annual" value={LEAVE_BALANCES.annual} color="bg-blue-500" />
                <BalanceItem label="Sick" value={LEAVE_BALANCES.sick} color="bg-rose-500" />
             </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function BalanceItem({ label, value, color }: { label: string; value: number; color: string }) {
    return (
        <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
                <div className={`h-2 w-2 rounded-full ${color}`}></div>
                <span className="text-sm font-medium">{label}</span>
            </div>
            <span className="text-sm font-bold">{value}d</span>
        </div>
    )
}